const video=document.querySelector('#video'),box=document.querySelector('.video-box'),light=document.querySelector('#lightbox'),gallery=document.querySelector('.gallery'),stills=[...document.querySelectorAll('.still')];let current=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const behavior=reduced?'instant':'smooth';
document.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>{box.innerHTML='<iframe src="https://drive.google.com/file/d/1v6-QSlSvhpsx-QB5ojr62uRDjndS3ly3/preview" title="Тизер фильма В комнате" allow="autoplay; fullscreen" allowfullscreen></iframe>';video.showModal()});
document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});d.addEventListener('close',()=>{if(d===video)box.innerHTML=''})});
function go(i){current=(i+stills.length)%stills.length;gallery.scrollTo({left:stills[current].offsetLeft-stills[0].offsetLeft,behavior})}document.querySelector('#prev').onclick=()=>go(current-1);document.querySelector('#next').onclick=()=>go(current+1);gallery.addEventListener('scroll',()=>{const width=stills[0].getBoundingClientRect().width+parseFloat(getComputedStyle(gallery).gap);current=Math.max(0,Math.min(3,Math.round(gallery.scrollLeft/width)));document.querySelector('#count').textContent=`0${current+1} / 04`},{passive:true});gallery.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();go(current+(e.key==='ArrowRight'?1:-1))}});
let selected=0;function showFrame(i){selected=(i+4)%4;light.querySelector('img').src=stills[selected].querySelector('img').src;document.querySelector('#light-count').textContent=`0${selected+1} / 04`}stills.forEach((b,i)=>b.onclick=()=>{showFrame(i);light.showModal()});document.querySelector('#light-prev').onclick=()=>showFrame(selected-1);document.querySelector('#light-next').onclick=()=>showFrame(selected+1);light.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')showFrame(selected-1);if(e.key==='ArrowRight')showFrame(selected+1)});let touchX;light.addEventListener('touchstart',e=>touchX=e.changedTouches[0].clientX,{passive:true});light.addEventListener('touchend',e=>{const delta=e.changedTouches[0].clientX-touchX;if(Math.abs(delta)>45)showFrame(selected+(delta<0?1:-1))},{passive:true});
function progress(){const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.progress').style.width=(max>0?scrollY/max*100:0)+'%'}addEventListener('scroll',progress,{passive:true});progress();
